/**
 * Returns a fallback or matching transparent Framer cutout for a given food name or category
 */
export function getFramerFoodImage(nameOrCategory = '') {
  const query = nameOrCategory.toLowerCase();
  
  if (query.includes('burger') || query.includes('smash') || query.includes('viande')) {
    if (query.includes('double')) return FRAMER_ASSETS.burgers.doubleSmash.src;
    if (query.includes('bacon')) return FRAMER_ASSETS.burgers.baconMelt.src;
    if (query.includes('veggie') || query.includes('vegetarien')) return FRAMER_ASSETS.burgers.veggieStack.src;
    return FRAMER_ASSETS.burgers.smashClassic.src;
  }
  
  if (query.includes('poulet') || query.includes('chicken') || query.includes('sandwich')) {
    return FRAMER_ASSETS.burgers.hotChicken.src;
  }
  
  if (query.includes('frite') || query.includes('fries') || query.includes('snack')) {
    return FRAMER_ASSETS.sides.cheeseFries.src;
  }
  
  if (query.includes('croissant') || query.includes('viennoiserie') || query.includes('amande')) {
    return FRAMER_ASSETS.pastries.croissantAmande.src;
  }
  
  if (query.includes('brioche') || query.includes('cannelle') || query.includes('bun')) {
    return FRAMER_ASSETS.pastries.cinnamonBun.src;
  }
  
  if (query.includes('cheesecake') || query.includes('gateau') || query.includes('cake') || query.includes('dessert')) {
    return FRAMER_ASSETS.pastries.burntCheesecake.src;
  }
  
  if (query.includes('tarte') || query.includes('citron')) {
    return FRAMER_ASSETS.pastries.tarteCitronMeringuee.src;
  }
  
  if (query.includes('cookie') || query.includes('biscuit')) {
    return FRAMER_ASSETS.pastries.cookieSelMarin.src;
  }
  
  if (query.includes('ramen') || query.includes('nouille') || query.includes('soup')) {
    return FRAMER_ASSETS.bowls.blackGarlicRamen.src;
  }
  
  if (query.includes('riz') || query.includes('wok') || query.includes('crevette') || query.includes('plat')) {
    return FRAMER_ASSETS.bowls.prawnFriedRice.src;
  }
  
  if (query.includes('panier') || query.includes('surprise') || query.includes('box')) {
    return FRAMER_ASSETS.pastries.boxSurpriseFika.src;
  }

  // Default delicious smash burger
  return FRAMER_ASSETS.burgers.smashClassic.src;
}

export default FRAMER_ASSETS;
